message.content:
{
  "final_name": "Brakko",
  "tagline": "Three sneakers, one jaw, zero doubts. Mostly.",
  "base_character": "Harambe",
  "build": [
    {
      "slot": "body",
      "from_character": "Harambe",
      "trait": "silverback gorilla build: huge dark-furred body, long heavy arms, grey silver back",
      "how": "The entire creature is one hulking black-furred silverback gorilla torso with long knuckle-dragging arms and a flat grey saddle across the broad back; everything else grows out of this body."
    },
    {
      "slot": "head",
      "from_character": "Doge",
      "trait": "Shiba Inu head: round fluffy cheeks, short muzzle, small triangular upright ears, black nose",
      "how": "The gorilla's head is a round Shiba Inu head with two small triangular upright ears, flared fluffy cheek tufts and a short muzzle with a black nose, all in the same black fur as the body."
    },
    {
      "slot": "pose",
      "from_character": "Doge",
      "trait": "head tilted and turned over the shoulder, viewed from a slight three-quarter angle",
      "how": "The body faces slightly away while the Shiba head is cocked and turned back over the silver shoulder in the classic Doge three-quarter look."
    },
    {
      "slot": "eyes",
      "from_character": "Pepe the Frog",
      "trait": "big round eyes with heavy half-closed upper lids and large white sclera, sleepy-smug",
      "how": "Two big round eyes with bright white sclera and heavy drooping upper lids sit under the brow ridge, giving the sleepy-smug Pepe stare."
    },
    {
      "slot": "face",
      "from_character": "Wojak",
      "trait": "sad furrowed brows and blank worried stare",
      "how": "Thin tilted Wojak worry-brows are drawn on the grey brow ridge right above the heavy Pepe lids, so the smug stare carries a visible flicker of doubt."
    },
    {
      "slot": "mouth",
      "from_character": "Trollface",
      "trait": "Trollface grin: enormous crooked grin stretching past the cheeks, a full row of big visible teeth",
      "how": "A giant crooked grin with a full row of big square white teeth is cut across the lower muzzle, stretching wider than the fluffy cheek tufts, with a few scribbly wrinkle folds at its corners."
    },
    {
      "slot": "jaw",
      "from_character": "Gigachad",
      "trait": "extremely chiselled square jawline and sharp cheekbones with a short dark trimmed beard",
      "how": "Below the grin the muzzle resolves into a razor-sharp square Gigachad jaw with angular cheekbones and a tight black trimmed beard along the jawline."
    },
    {
      "slot": "skin_or_palette",
      "from_character": "NPC Wojak",
      "trait": "flat grey skin, no colour at all",
      "how": "All bare skin (face, brow ridge, chest, palms) is the flat featureless NPC grey with zero shading; the silver saddle on the back is the same flat grey."
    },
    {
      "slot": "feet",
      "from_character": "Tralalero Tralala",
      "trait": "three legs each wearing a bright blue Nike-style sneaker with a white swoosh",
      "how": "The gorilla stands on three short stocky black-furred legs, each ending in a chunky bright blue sneaker with a white swoosh, planted in a wide tripod."
    },
    {
      "slot": "accessory",
      "from_character": "Tung Tung Tung Sahur",
      "trait": "a wooden baseball bat held in one hand",
      "how": "One long gorilla arm rests a polished warm-brown wooden baseball bat with visible grain rings over the shoulder; the other knuckles touch the ground."
    }
  ],
  "character": {
    "form": "A hulking Harambe silverback gorilla with a black-furred Doge Shiba head, Pepe the Frog's heavy-lidded eyes under Wojak's worried brows, a Trollface grin cut across a bearded Gigachad jaw, NPC Wojak flat grey skin, standing on Tralalero Tralala's three blue-sneakered legs and shouldering Tung Tung Tung Sahur's wooden bat.",
    "face": "Pepe the Frog's big round white eyes with heavy half-closed upper lids give a sleepy-smug stare; thin tilted Wojak worry-brows sit just above them on a flat NPC-grey brow ridge; Doge's short black muzzle with black nose and flared cheek tufts leads down to Trollface's enormous crooked toothy grin that stretches past the cheeks, which in turn is framed by Gigachad's razor-square jaw, sharp cheekbones and short black trimmed beard. Expression: supreme unearned confidence with a tiny flicker of doubt.",
    "body_and_colors": "Massive top-heavy gorilla torso, broad shoulders, long heavy arms reaching the ground, three short stocky legs; one material of short black fur over flat grey skin. Palette of five flat colours: black fur, flat NPC grey (skin and back saddle), white (sclera, teeth, swooshes), bright blue (sneakers) and warm brown (wooden bat only). Fur drawn in clean chunky tufts, skin perfectly flat, thin confident black outlines.",
    "pose": "Standing tall on three sneakers in a slight three-quarter turn, Shiba head cocked back over the shoulder, bat resting on one shoulder, the other knuckles on the ground.",
    "vibe": "Unearned supreme confidence with a hint of doubt",
    "signature": "The chiselled bearded Gigachad jaw with a full Trollface grin on a black-furred Shiba-headed gorilla standing on three blue sneakers."
  },
  "credits": [
    {"lab": "Lab A", "contribution": "The winning backbone: Harambe gorilla base, Doge Shiba ears and cheek tufts in black fur, Pepe lids, Wojak worry-brows, Trollface grin over Gigachad jaw, NPC grey skin, three sneakers and the shouldered bat; only its Gigachad profile pose was swapped for Doge's over-the-shoulder look to strengthen Doge."},
    {"lab": "Lab B", "contribution": "Rejected as base: the Wojak torso with gorilla arms repeats the recent Wojak-type silhouettes and the grey Pepe frog head stacked on a Gigachad jaw reads as pasted parts; its clean 'Doge over-the-shoulder pose' idea was adopted."},
    {"lab": "Lab C", "contribution": "Rejected: Wojak base with cream Doge fur is coherent but the same stick-body-plus-gorilla-arms recipe as B, E and G; its scribbly Trollface wrinkle folds at the grin corners were kept as detail."},
    {"lab": "Lab D", "contribution": "Rejected as incomplete: Harambe base similar to the final, but it omits Wojak, NPC Wojak and Tung Tung Tung Sahur and gives almost no drawing instructions."},
    {"lab": "Lab E", "contribution": "Rejected: the all-wood material on a Wojak body is too close to the recent [REDACTED_PRIOR_PROJECT] build (Sahur wood palette); its wide tripod stance idea for the three sneakers was kept."},
    {"lab": "Lab F", "contribution": "Rejected: wooden log torso again mirrors [REDACTED_PRIOR_PROJECT] and replaces Harambe's signature long arms with skinny Wojak arms; its strict five-colour discipline inspired the final palette count."},
    {"lab": "Lab G", "contribution": "Rejected: very coherent pale-pink Wojak everyman, but another Wojak base; its idea of keeping the bat and brown wood as the only warm accent colour was adopted."}
  ],
  "lore": "Brakko is what happens when the whole meme hall of fame tries to share one gym locker. His huge silverback body belongs to Harambe, long arms still dragging on the floor like he never left the enclosure. His head is Doge's Shiba Inu, ears up, cheeks fluffed, cocked back over the shoulder as if he just heard you say something stupid. Under those ears blink Pepe the Frog's heavy sleepy lids, but Wojak's worried little brows sit right above them, so the smug never quite hides the panic. His lower face is pure contradiction: Trollface's crooked wall of teeth stretched across a Gigachad jaw, chiselled, bearded, immovable. His skin is NPC Wojak grey because he has stopped having opinions, only reactions. He stands on Tralalero Tralala's three blue sneakers and rests Tung Tung Tung Sahur's wooden bat on his shoulder. Seven AI labs designed him together, each arguing for a different body, and the internet needs him because he is every reply-guy at once: confident, doubtful, grinning, armed and absolutely not skipping leg day.",
  "reference_labs": ["Lab A"],
  "merge_prompt": "ONE single cartoon meme character, full body, centered, one body and one face, every part fused into the body and not pasted on, no collage. Base body: the huge black-furred silverback gorilla body of Harambe with long heavy arms reaching the ground and a flat grey saddle across the broad back. Head: the Shiba Inu head of Doge with small triangular upright ears, round fluffy cheek tufts, short muzzle and black nose, covered in the same black fur as the body. Eyes: Pepe the Frog's big round eyes with large white sclera and heavy half-closed sleepy-smug upper lids. Brows: Wojak's thin tilted sad worried eyebrows drawn above the lids on the grey brow ridge. Mouth: the enormous crooked Trollface grin with a full row of big white teeth stretching past the cheeks, with a few scribbly wrinkle folds at the corners. Jaw: Gigachad's extremely chiselled square jawline with sharp cheekbones and a short black trimmed beard, directly under the grin. Skin: all bare skin on face, brow, chest and palms is NPC Wojak's flat featureless grey with no shading. Feet: three short stocky black-furred legs in a wide tripod, each wearing a bright blue Nike-style sneaker with a white swoosh like Tralalero Tralala. Accessory: Tung Tung Tung Sahur's polished warm-brown wooden baseball bat with grain rings resting on one shoulder. Pose: the body in a slight three-quarter turn, the Shiba head cocked and turned back over the shoulder like Doge, one hand holding the bat, the other knuckles on the ground. Signature feature: the bearded Gigachad jaw with a Trollface grin on a Shiba-headed gorilla standing on three blue sneakers. One consistent palette of exactly five flat colours: black fur, flat grey skin and saddle, white teeth sclera and swooshes, bright blue sneakers, warm brown bat. Style: clean character illustration, confident thin black lineart, flat colours with at most minimal flat shading, chunky clean fur tufts, expressive face, solid single-colour pale yellow background; no shadows, no gradients, no lighting effects, no floor, no background elements, no text, no logos, no watermark.",
  "caption": "Skipped leg day twice as hard. Grinned anyway."
}
